namespace sv_b8940e64341f4b91829c8bb2499525f3.Client.Models;

public class Shipment
{
    public required string TrackingNumber { get; set; }
    public required string Status { get; set; }
    public required string Location { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public List<StatusUpdate> StatusUpdates { get; set; } = [];
}

public class StatusUpdate
{
    public required string Description { get; set; }
    public required string Location { get; set; }
    public DateTime Timestamp { get; set; }
}

using sv_b8940e64341f4b91829c8bb2499525f3.Client.Models;

namespace sv_b8940e64341f4b91829c8bb2499525f3.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net;
using System.Net.Http.Json;
using sv_b8940e64341f4b91829c8bb2499525f3.Client.Models;

namespace sv_b8940e64341f4b91829c8bb2499525f3.Client.Services;

/// <summary>
/// IShipmentService implementation for WebAssembly — calls the server API over HTTP.
/// </summary>
public class ShipmentApiClient(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

using sv_b8940e64341f4b91829c8bb2499525f3.Client.Models;
using sv_b8940e64341f4b91829c8bb2499525f3.Client.Services;

namespace sv_b8940e64341f4b91829c8bb2499525f3.Services;

/// <summary>
/// Server-side IShipmentService that simulates a slow backend with seeded data.
/// </summary>
public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Shipments = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Memphis, TN",
            EstimatedDelivery = new DateTime(2026, 6, 7, 17, 0, 0, DateTimeKind.Utc),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Los Angeles, CA", Timestamp = new DateTime(2026, 6, 1, 9, 0, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Departed facility", Location = "Los Angeles, CA", Timestamp = new DateTime(2026, 6, 1, 14, 30, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Arrived at hub", Location = "Memphis, TN", Timestamp = new DateTime(2026, 6, 2, 6, 15, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "In transit to destination", Location = "Memphis, TN", Timestamp = new DateTime(2026, 6, 2, 18, 0, 0, DateTimeKind.Utc) },
            ]
        },
        ["PKG-002"] = new Shipment
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "New York, NY",
            EstimatedDelivery = new DateTime(2026, 6, 2, 12, 0, 0, DateTimeKind.Utc),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Chicago, IL", Timestamp = new DateTime(2026, 5, 30, 10, 0, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Arrived at sort facility", Location = "Indianapolis, IN", Timestamp = new DateTime(2026, 5, 31, 3, 0, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Out for delivery", Location = "New York, NY", Timestamp = new DateTime(2026, 6, 2, 7, 45, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Delivered — signed by J. Smith", Location = "New York, NY", Timestamp = new DateTime(2026, 6, 2, 11, 20, 0, DateTimeKind.Utc) },
            ]
        },
        ["PKG-003"] = new Shipment
        {
            TrackingNumber = "PKG-003",
            Status = "Label Created",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTime(2026, 6, 10, 20, 0, 0, DateTimeKind.Utc),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Shipping label created", Location = "Seattle, WA", Timestamp = new DateTime(2026, 6, 3, 8, 0, 0, DateTimeKind.Utc) },
            ]
        },
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        Shipments.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_b8940e64341f4b91829c8bb2499525f3.Client.Models
@using sv_b8940e64341f4b91829c8bb2499525f3.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h3>Shipment Tracking</h3>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
        Loading shipment <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p><strong>Something went wrong.</strong></p>
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning" role="alert">
        No shipment found for tracking number <strong>@TrackingNumber</strong>.
    </div>
}
else
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">@_shipment.TrackingNumber</h5>
            <p><strong>Status:</strong> @_shipment.Status</p>
            <p><strong>Location:</strong> @_shipment.Location</p>
            @if (_shipment.EstimatedDelivery.HasValue)
            {
                <p><strong>Estimated Delivery:</strong> @_shipment.EstimatedDelivery.Value.ToString("f")</p>
            }
        </div>
    </div>

    @if (_shipment.StatusUpdates.Count > 0)
    {
        <h5>Tracking History</h5>
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Date &amp; Time</th>
                    <th>Location</th>
                    <th>Description</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates.OrderByDescending(u => u.Timestamp))
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Location</td>
                        <td>@update.Description</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;

    private CancellationTokenSource? _cts;
    private string _loadedTrackingNumber = string.Empty;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(_loadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase) && !_loading)
            return;

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request (handles mid-navigation cancellation)
        CancelPending();

        _loadedTrackingNumber = TrackingNumber;
        _shipment = null;
        _errorMessage = null;
        _loading = true;

        var cts = new CancellationTokenSource();
        _cts = cts;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, cts.Token);
        }
        catch (OperationCanceledException)
        {
            // Request was cancelled — either navigating away or switching tracking numbers. No UI update needed.
            return;
        }
        catch (TimeoutException)
        {
            Logger.LogError("Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError("Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "An unexpected error occurred while loading shipment details. Please try again.";
        }
        finally
        {
            // Only update loading state if this is still the active request
            if (_cts == cts)
            {
                _loading = false;
            }
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    private void CancelPending()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPending();
    }
}

